var datum, txt;

// Beschreibe diese Funktion …
async function Logfile(datum, txt) {
    if (getState('0_userdata.0.go-e.DebugAktiv').val) {
      require('fs').appendFileSync('/opt/iobroker/log/' + datum + ' - Cupra.log', formatDate(new Date(), "hh:mm:ss") + " \t" + txt + "\n");}
}


// Grid Offset mit Wolkenzähler anpassen
on({ id: [].concat(['javascript.0.Wolken-PV_Caddy.Wolkenzaehler_PVCaddy']).concat(['0_userdata.0.go-e.1P']).concat(['0_userdata.0.go-e.3P']), change: 'ne' }, async (obj) => {
  if (getState('javascript.0.Wolken-PV_Halle.Wolkenzaehler_PVHalle_Aktiv').val) {
    if (getState('0_userdata.0.go-e.1P').val) {
      setState('0_userdata.0.go-e.minPV' /* minPVÜberschuss */, (1500 - Math.min(Math.max(10 - getState('javascript.0.Wolken-PV_Caddy.Wolkenzaehler_PVCaddy').val, 0), 10) * 100));
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '# go-E / Gridoffset / minPVÜberschuss');
    } else if (getState('0_userdata.0.go-e.3P').val) {
      setState('0_userdata.0.go-e.minPV' /* minPVÜberschuss */, (4500 - Math.min(Math.max(10 - getState('javascript.0.Wolken-PV_Caddy.Wolkenzaehler_PVCaddy').val, 0), 10) * 300));
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '# go-E / Gridoffset / minPVÜberschuss');
    }
  } else {
    if (getState('0_userdata.0.go-e.1P').val) {
      setState('0_userdata.0.go-e.minPV' /* minPVÜberschuss */, 1500);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '# go-E / Gridoffset / minPVÜberschuss = 1500');
    } else if (getState('0_userdata.0.go-e.3P').val) {
      setState('0_userdata.0.go-e.minPV' /* minPVÜberschuss */, 4500);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '# go-E / Gridoffset / minPVÜberschuss = 4500');
    }
  }
});
on({ id: 'javascript.0.Wolken-PV_Halle.Wolkenzaehler_PVHalle_Aktiv' /* WolkenzaehlerPVCaddyAktiv */, val: false }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (getState('0_userdata.0.go-e.1P').val) {
    setState('0_userdata.0.go-e.minPV' /* minPVÜberschuss */, 1500);
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '# go-E / Gridoffset / minPVÜberschuss 1500');
  } else if (getState('0_userdata.0.go-e.3P').val) {
    setState('0_userdata.0.go-e.minPV' /* minPVÜberschuss */, 4500);
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '# go-E / Gridoffset / minPVÜberschuss 4500');
  }
});
on({ id: '0_userdata.0.go-e.minPV' /* minPVÜberschuss */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  console.debug(('go-E Wolkenzähler hat GridOffset angepasst auf: ' + String(getState('0_userdata.0.go-e.minPV').val)));
});


